def transform(grid):
    nz = [(r, c, v) for r, row in enumerate(grid) for c, v in enumerate(row) if v]
    out = [[0] * len(grid[0]) for _ in grid]
    bottom = max(r for r, c, v in nz)
    for r, c, v in nz:
        nc = c + r - bottom
        if 0 <= nc < len(grid[0]):
            out[r][nc] = v
    return out
